update tj_volume
set title = #{title}, ji = #{ji}, sort_order = #{sortOrder}
where volume_id = #{volumeId}

update tj_reign
set volume_id = #{volumeId}, emperor_name = #{emperorName}, reign_name = #{reignName},
    year_anno = #{yearAnno}, year_int = #{yearInt}, sort_order = #{sortOrder}
where reign_id = #{reignId}
